// План specs/mobile-nav.md 2.1–2.4 (кейс .qa/tests/mobile-nav/MN-02). Admin, компания «test». Только просмотр (@prod-safe):
// меню открывается и замеряется, пункты не нажимаются. 375×812 — iPhone (WebKit), 390×844 — Chrome (Android-прогон).
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, ITEMS, Lang, PHONES, openMoreMenu, restoreCompany, scrollOverflows } from './mobile-nav-helpers';

test.use({ storageState: ADMIN_STATE });

for (const phone of PHONES) {
  test.describe(`Phone ${phone.label}: "More" menu fits without scrolling (#e9cbda)`, () => {
    test.use({ viewport: phone.viewport });

    for (const lang of ['en', 'he'] as Lang[]) {
      test(`More menu ${phone.label} ${lang.toUpperCase()}: no vertical scroll, last item "${ITEMS[lang][ITEMS[lang].length - 1]}" inside the screen #e9cbda ${phone.tag} @prod-safe`, async ({ page }) => {
        try {
          const { panel, items } = await openMoreMenu(page, lang);

          // Комментарий программиста: כל הפריטים נכנסים בלי גלילה (375×812, 390×844, גם בעברית); требование #c264a7.
          expect(await scrollOverflows(panel, items[0]), 'контейнер меню без вертикальной прокрутки').toEqual([]);

          const last = (await items[items.length - 1].boundingBox())!;
          const pb = (await panel.boundingBox())!;
          const vh = phone.viewport.height;
          expect(last.y, 'последний пункт: верх на экране').toBeGreaterThanOrEqual(0);
          expect(last.y + last.height, `последний пункт: низ ≤ высоты экрана ${vh}`).toBeLessThanOrEqual(vh + 0.5);
          expect(last.y + last.height, 'последний пункт: внутри панели меню').toBeLessThanOrEqual(pb.y + pb.height + 0.5);
          await expect(items[items.length - 1]).toBeInViewport({ ratio: 1 });
        } finally {
          await restoreCompany(page);
        }
      });
    }
  });
}
